const table=(name,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${name}"><table><thead><tr><th>확인 항목</th><th>정리할 내용</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div>`;
